// Sandbox-only dev runtime: remembers where each element was created, keyed by
// the props object React keeps as fiber.memoizedProps. Several bundles may load
// this file; they all feed the one registry the first instance published.
const runtime = require("react/jsx-dev-runtime");

const REGISTRY_GLOBAL = "__MI_ANCHORS__";

function createRegistry() {
  const anchors = new WeakMap();
  return { version: 1, anchors, get: (props) => anchors.get(props) };
}

const registry = globalThis[REGISTRY_GLOBAL] || (globalThis[REGISTRY_GLOBAL] = createRegistry());

function jsxDEV(type, props, key, isStatic, source, self) {
  const element = runtime.jsxDEV(type, props, key, isStatic, source, self);
  if (
    source &&
    typeof source.fileName === "string" &&
    typeof source.lineNumber === "number" &&
    typeof source.columnNumber === "number" &&
    element &&
    element.props &&
    typeof element.props === "object"
  ) {
    registry.anchors.set(element.props, {
      file: source.fileName,
      line: source.lineNumber,
      col: source.columnNumber,
    });
  }
  return element;
}

module.exports = { Fragment: runtime.Fragment, jsxDEV };
